```go
// Lookup returns the file with the given name, or nil and false if no such file exists.
func (a *Archive) Lookup(name string) (*File, bool) {
	for i := range a.Files {
		if a.Files[i].Name == name {
			return &a.Files[i], true
		}
	}
	return nil, false
}
```
